import {SCHEMA,KINDS,MAX_BYTES,exportReport,importReport} from './file-problem.js';
const $=id=>document.getElementById(id),form=$('problem-form');let raw=null,epoch=0;
for(const kind of KINDS){const o=document.createElement('option');o.value=kind;o.textContent=kind;$('kind').append(o);}
const fields=[['url','HTTPS source reference (optional; destination unverified)',false],['filename','Exact filename or native file identity',true],['version','File version or UNKNOWN',true],['locator','Page, region, whole-file scope or UNKNOWN',true],['sha256','Source SHA-256 (optional reference)',false],['method','Method, tool/version, settings and steps used',true],['expected','What you expected',true],['observed','What actually happened',true],['evidence','Evidence checked and attempt receipts or references',true],['uncertainty','What remains unknown',true],['contributor','Contributor credit (self-declared)',true]];
for(const [id,label,required] of fields){const l=document.createElement('label');l.textContent=label;const e=document.createElement(['method','expected','observed','evidence','uncertainty'].includes(id)?'textarea':'input');e.id=id;e.required=required;e.maxLength=id==='contributor'?120:id==='url'?2048:id==='sha256'?64:['filename','version','locator'].includes(id)?1000:id==='method'?4000:8000;l.append(e);$('problem-fields').append(l);}
const value=id=>$(id).value.trim();const snapshot=()=>JSON.stringify([...form.querySelectorAll('input,textarea,select')].map(e=>[e.id,e.value]));
function clear(){raw=null;$('problem-inspection').hidden=true;}
form.addEventListener('input',()=>{epoch++;clear();$('problem-status').textContent='Draft changed; prepare again before downloading.';});
function inspect(text){raw=text;$('problem-preview').textContent=text;$('problem-inspection').hidden=false;$('inspection-heading').focus();}
form.onsubmit=async event=>{event.preventDefault();const ticket=++epoch,before=snapshot();clear();try{const report={schema:SCHEMA,kind:value('kind'),source:{url:value('url')||null,filename:value('filename'),version:value('version'),locator:value('locator'),sha256:value('sha256')||null},method:value('method'),expected:value('expected'),observed:value('observed'),evidence:value('evidence'),uncertainty:value('uncertainty'),contributor:value('contributor'),assistance:value('assistance'),createdAt:new Date().toISOString()};const text=await exportReport(report);if(ticket!==epoch||before!==snapshot())throw Error('Draft changed during preparation; prepare again.');inspect(text);$('problem-status').textContent='Prepared locally. Inspect before sharing; nothing uploaded.';}catch(e){if(ticket===epoch)$('problem-status').textContent=e.message;}};
$('problem-download').onclick=()=>{if(!raw)return;const url=URL.createObjectURL(new Blob([raw],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='file-problem-report.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('problem-reopen').onchange=async event=>{const file=event.target.files[0];if(!file)return;const ticket=++epoch;clear();try{if(file.size>MAX_BYTES)throw Error('Choose report metadata under 64 KiB, not a source file');const text=await file.text();await importReport(text);if(ticket!==epoch)return;inspect(text);$('problem-status').textContent='Report digest checked; draft unchanged. Identity and diagnosis remain unverified.';}catch(e){if(ticket===epoch)$('problem-status').textContent=e.message;}finally{event.target.value='';}};
